/// 幂等创建：命中 requests → 返回原 note（AC-02）。
/// 返回 JSON：{"ok":..,"err_code":..,"note":{文档},"receipt":{...}}
/// 条件更新：expected_revision 不符 → revision_conflict（AC-04）。
/// 幂等重放先于 revision 检查（AC-02）。
/// 元数据变更（state/pinned/tags/folder）
/// 读取单个文档 JSON（含 trashed）；无 → ""
/// active 列表 JSON 数组，seq 降序（新在前）
/// 搜索：title/body 子串，大小写不敏感（SQL lower + LIKE）
/// 诊断状态
fn ensure_schema(db: a2r_std::sqlite::SqliteDb) {
    db.exec("PRAGMA busy_timeout=3000");
    db.exec("PRAGMA journal_mode=WAL");
    db.exec("CREATE TABLE IF NOT EXISTS notes(note_id TEXT PRIMARY KEY, legacy_id INTEGER UNIQUE, revision INTEGER NOT NULL DEFAULT 1, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', tags_json TEXT NOT NULL DEFAULT '[]', color TEXT NOT NULL DEFAULT '', pinned INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'active', folder TEXT NOT NULL DEFAULT '', seq INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '')");
    db.exec("CREATE TABLE IF NOT EXISTS requests(request_id TEXT PRIMARY KEY, note_id TEXT NOT NULL, kind TEXT NOT NULL)");
    db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)");
}

fn open_conn() -> impl SqliteDb {
    let mut p: String = db_path();
    return a2r_std::sqlite::open(&p.as_str());
}

/// 按 note_id 载入文档 JSON；无 → ""
fn load_doc_json(db: a2r_std::sqlite::SqliteDb, note_id: &str) -> String {
    let mut esc: String = serde_json::to_string(&note_id).unwrap_or_default();
    let mut sql: String = format!("{}{}", format!("{}{}", format!("{}{}", "SELECT ", note_select_cols()), " FROM notes WHERE note_id="), esc);
    let mut rows: Vec<Vec<String>> = db.query(sql);
    if (rows.len() as i64) < 1 {
        return "".to_string();
    }
    let mut row = rows[0].clone();
    return row_to_doc_json(row.clone());
}

/// 行 → 文档 JSON（13 列固定序）
fn row_to_doc_json(row: Vec<String>) -> String {
    let mut s: String = format!("{}{}", "{\"schema_version\":1,\"note_id\":", serde_json::to_string(&row[0].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", s, ",\"legacy_id\":"), row[1].clone());
    s = format!("{}{}", format!("{}{}", s, ",\"revision\":"), row[2].clone());
    s = format!("{}{}", format!("{}{}", s, ",\"title\":"), serde_json::to_string(&row[3].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", s, ",\"body\":"), serde_json::to_string(&row[4].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", s, ",\"tags\":"), row[5].clone());
    s = format!("{}{}", format!("{}{}", s, ",\"color\":"), serde_json::to_string(&row[6].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", s, ",\"pinned\":"), row[7].clone());
    s = format!("{}{}", format!("{}{}", s, ",\"state\":"), serde_json::to_string(&row[8].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", s, ",\"folder\":"), serde_json::to_string(&row[9].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", s, ",\"seq\":"), row[10].clone());
    s = format!("{}{}", format!("{}{}", s, ",\"created_at\":"), serde_json::to_string(&row[11].clone()).unwrap_or_default());
    s = format!("{}{}", format!("{}{}", format!("{}{}", s, ",\"updated_at\":"), serde_json::to_string(&row[12].clone()).unwrap_or_default()), "}");
    return s;
}

