/// 括号配平打捞：截断 JSON 中提取完整对象（字节偏移扫描）
fn salvage_objects(raw: &str) -> String {
    let mut out: String = "[".to_string();
    let mut depth: i64 = 0;
    let mut obj_start: i64 = -1;
    let mut in_str: bool = false;
    let mut esc: bool = false;
    let mut byte_pos: i64 = 0;
    let mut n: i64 = (raw.len() as i64);
    for i in 0..n {
        let mut cp: i64 = raw.chars().nth((i) as usize).unwrap_or('\0') as i64;
        if cp != 0 {
            if in_str {
                if esc {
                    esc = false;
                } else {
                    if cp == 92 {
                        esc = true;
                    } else {
                        if cp == 34 {
                            in_str = false;
                        }                    }
                }
            } else {
                if cp == 34 {
                    in_str = true;
                } else {
                    if cp == 123 {
                        depth = depth + 1;
                        if depth == 1 {
                            obj_start = byte_pos;
                        }                    } else {
                        if cp == 125 {
                            if depth > 0 {
                                depth = depth - 1;
                                if depth == 0 {
                                    if obj_start >= 0 {
                                        let mut endb: i64 = byte_pos + 1;
                                        let mut piece: String = raw[(obj_start) as usize..(endb) as usize].to_string();
                                        if out != "[" {
                                            out = format!("{}{}", out, ",");
                                        }                                        out = format!("{}{}", out, serde_json::to_string(&piece).unwrap_or_default());
                                    }                                    obj_start = -1;
                                }                            }                        }                    }
                }
            }
            byte_pos = byte_pos + 1;
        }
    }
    out = format!("{}{}", out, "]");
    return out;
}

fn ensure_schema() {
    let mut db: a2r_std::sqlite::SqliteDb = a2r_std::sqlite::open(db_path().as_str());
    db.exec("PRAGMA busy_timeout=3000");
    db.exec("PRAGMA journal_mode=WAL");
    db.exec("CREATE TABLE IF NOT EXISTS notes(note_id TEXT PRIMARY KEY, legacy_id INTEGER UNIQUE, revision INTEGER NOT NULL DEFAULT 1, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', tags_json TEXT NOT NULL DEFAULT '[]', color TEXT NOT NULL DEFAULT '', pinned INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'active', folder TEXT NOT NULL DEFAULT '', seq INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '')");
    db.exec("CREATE TABLE IF NOT EXISTS requests(request_id TEXT PRIMARY KEY, note_id TEXT NOT NULL, kind TEXT NOT NULL)");
    db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)");
}

