/// 事务内幂等重放：requests 命中 → 返回文档 JSON；未命中 → ""
fn replay_in_txn(db: a2r_std::sqlite::SqliteDb, rid: &str) -> String {
    if rid == "" {
        return "".to_string();
    }
    let mut esc: String = serde_json::to_string(&rid).unwrap_or_default();
    let mut sql: String = format!("{}{}", "SELECT note_id FROM requests WHERE request_id=", esc);
    let mut rows: Vec<Vec<String>> = db.query(sql);
    if (rows.len() as i64) < 1 {
        return "".to_string();
    }
    let mut row = rows[0].clone();
    return load_doc_json_on(db.clone(), row[0].as_str());
}

fn load_doc_json_on(db: a2r_std::sqlite::SqliteDb, note_id: &str) -> String {
    let mut esc: String = serde_json::to_string(&note_id).unwrap_or_default();
    let mut sql: String = format!("{}{}", format!("{}{}", format!("{}{}", "SELECT ", note_select_cols()), " FROM notes WHERE note_id="), esc);
    let mut rows: Vec<Vec<String>> = db.query(sql);
    if (rows.len() as i64) < 1 {
        return "".to_string();
    }
    let mut row = rows[0].clone();
    return row_to_doc_json(row.clone());
}

fn load_doc_json(note_id: &str) -> String {
    let mut db: a2r_std::sqlite::SqliteDb = a2r_std::sqlite::open(db_path().as_str());
    return load_doc_json_on(db.clone(), note_id);
}

